private lemma abs_bernoulliFun_le (s : ℕ) (x : ℝ) (hx : x ∈ Icc 0 1) :
    |bernoulliFun s x| ≤ ∑ i ∈ Finset.range (s + 1),
      |(_root_.bernoulli (s - i) : ℝ) * (s.choose i : ℝ)|

private lemma integral_saw_eq_integral_presaw :
    ∫ x in a..a + 1, saw s x • iteratedDerivWithin s f t x =
      ∫ x in a..a + 1, presaw s a x • iteratedDerivWithin s f t x

private lemma trapezoid_sum_succ :
    trapezoid_sum f a (n + 1) =
      trapezoid_sum f a n + (2⁻¹ : ℝ) • (f (a + n) + f (a + n + 1))

private lemma trapezoid_sum_eq_sum_Icc_sub (f : ℝ → E) (a : ℤ) (n : ℕ) :
    trapezoid_sum f a n =
      ∑ k ∈ Finset.Icc a (a + n), f k - (2⁻¹ : ℝ) • (f a + f (a + n))

private lemma coeff_eq_zero_of_sum_norm_sq_eq_zero
    {ι : Type*} [Fintype ι] {a : ι → ℂ}
    (h : ∑ r, ‖a r‖ ^ 2 = 0) : ∀ r, a r = 0

private lemma smoothingKernel_aestronglyMeasurable (N : ℝ) (hN : 0 < N)
    (left right : ℝ) (hleft_right : left ≤ right) :
    AEStronglyMeasurable (smoothingKernel N left right)

private lemma extract_strictMono_subseq {P : ℕ → Prop}
    (h : ∀ j, ∃ i ≥ j, P i) :
    ∃ φ : ℕ → ℕ, StrictMono φ ∧ ∀ n, P (φ n)

private lemma sum_stdAddChar_mul_eq_ite (q m : ℕ) [NeZero q] :
    (∑ h : ZMod q, ZMod.stdAddChar (h * (m : ZMod q))) =
      if q ∣ m then (q : ℂ) else 0

private lemma stdAddChar_mul_nat_eq_fourierChar (q m : ℕ) [NeZero q] (h : ZMod q) :
    ZMod.stdAddChar (h * (m : ZMod q)) =
      (𝐞 ((h.val : ℝ) * (m : ℝ) / q) : ℂ)

private lemma residue_upper_endpoint_le (N : ℝ) (b q r : ℕ)
    (hq : 0 < q) (hr : r < q) (hb : (b : ℝ) ≤ 2 * N) :
    (b - r) / q ≤ ⌊2 * residueScale N q r⌋₊ + 1

theorem IsExponentSumBound.mono {α : ℝ≥0} {β γ : ℝ}
    (hβ : IsExponentSumBound α β) (hβγ : β ≤ γ) :
    IsExponentSumBound α γ

theorem HasPhaseDerivBound.of_le {F : ℝ → ℝ} {m n : ℕ} {K : ℝ}
    (hF : HasPhaseDerivBound F n K) (hmn : m ≤ n) :
    HasPhaseDerivBound F m K

theorem IsModelPhaseFunctionWith.comp_affine_tendsto_id
    {F : VariableFunction (VariableObject.fixed ℝ) ℝ} {σ : ℝ}
    (hF : IsModelPhaseFunctionWith F σ) {c d : VariableObject ℝ}
    (hc : Tendsto c atTop (𝓝 1)) (hd : Tendsto d atTop (𝓝 0))
    (hmap : ∀ i, Set.MapsTo (fun u ↦ c i * u + d i) phaseInterval phaseInterval) :
    IsModelPhaseFunctionWith (fun i u ↦ F i (c i * u + d i)) σ
